interface.definition:
a!localVariables(
  local!user: if(
    a!isNotNullOrEmpty(ri!userid),
    #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1277768"(userid: ri!userid),
    null()
  ),
  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"_a-0000eef8-4604-8000-9e54-011c48011c48_1144871"(user: local!user)
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true,
          saveInto: {
            if(
              ri!isUpdate,                              /* ✅ Direct boolean check */
              {
                /* Update flow — modify existing user */
                a!save(
                  target: local!user[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/65e31e06-83ee-4374-a16b-0492412c131d"],
                  value: loggedInUser()
                ),
                a!save(
                  target: local!user[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/ebd15b9a-55f0-41b2-bef4-1be8961a4e38"],
                  value: now()
                )
              },
              {
                /* Create flow — set initial fields on local!user */
                a!save(
                  target: local!user[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/7791c860-1d5f-4680-b36f-ba0a1b2285b5"],
                  value: loggedInUser()
                ),
                a!save(
                  target: local!user[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/4a3247cf-4803-48ad-ae12-8e28434c7087"],
                  value: now()
                ),
                a!save(
                  target: local!user[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/811b9c80-c907-4d49-9262-702a73d2e7d1"],
                  value: true()
                )
              }
            ),
            /* Save the modified user record back to PM */
            a!save(
              target: ri!user,
              value: local!user
            ),
            a!save(
              target: ri!button,
              value: #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463"
            )
          },
          loadingIndicator: true,
          style: "SOLID"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          saveInto: {
            a!save(
              target: ri!button,
              value: #"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: if(
        ri!isUpdate,                                    /* ✅ Fixed */
        "Update User",
        "Create User"
      ),
      secondaryText: if(
        ri!isUpdate,                                    /* ✅ Fixed */
        "Updating User Details",
        "Enter User details"
      ),
      backgroundColor: "ACCENT"
    ),
    showTitleBarDivider: false
  )
)
